    export default {
        props: {
            careersconsultants: {
                type: Array,
                default: () => [],
            },
            question1Ans: {
                type: String,
                default: '',
            },
        },

        data() {
            return {
                sliderOptions: {
                    autoPlay: false,
                    loop: true,
                    autoHeight: true,
                    slidesPerView: 1,
                    spaceBetween: 10,
                    touchRatio: 1,
                    init: false,
                    pagination: {
                        el: '.swiper-pagination-career-consultant',
                        clickable: true,

                        renderBullet: (index, className) => {
                            return `<p aria-label="Bullet Icon" class="career-slider-bullet-icon ${className}"></p>`;
                        },
                    },
                    breakpoints: {
                        640: {
                            slidesPerView: 1,
                            slidesPerGroup: 1,
                        },
                        768: {
                            slidesPerView: 2,
                            slidesPerGroup: 2,
                        },
                        1024: {
                            slidesPerView: 4,
                            slidesPerGroup: 4,
                        },
                        1200: {
                            slidesPerView: 4,
                            slidesPerGroup: 4,
                        },
                    },
                },
            };
        },

        mounted() {
            this.careerConsultantSlider.init();
        },
    };
